<?php $daily = array_slice($daily,-7); $firstName = explode(' ', trim($user['full_name']))[0]; $hour = (int) gmdate('G'); $greeting = $hour < 12 ? 'Good morning' : ($hour < 18 ? 'Good afternoon' : 'Good evening'); $reviewedLater = (int) $stats['today_scheduled']; $reviewWorkload = $reviewedLater + (int) $stats['due']; $reviewPercent = $reviewWorkload > 0 ? (int) round($reviewedLater / $reviewWorkload * 100) : 0; ?>
<header class="page-heading"><div><p class="eyebrow">YOUR LEARNING SPACE</p><h1><?= e($greeting) ?>, <?= e($firstName) ?><span class="heading-dot">.</span></h1><p>Ready to make progress on your learning goals?</p></div><a class="btn btn-primary" href="<?= e(url('/decks/create')) ?>"><?= icon('plus') ?> Create a deck</a></header>
<section class="stats-grid" aria-label="Learning overview">
<?php foreach ([['decks','Total decks','decks'],['cards','Total flashcards','cards'],['due','Due for review','clock'],['current_streak','Day study streak','flame']] as [$key,$label,$symbol]): ?>
<article class="stat-card"><span class="stat-icon"><?= icon($symbol,22) ?></span><div><span class="stat-label"><?= e($label) ?></span><strong class="stat-value"><?= (int) $stats[$key] ?></strong></div><?php if ($key === 'current_streak'): ?><span class="stat-footnote">Built one day at a time</span><?php endif; ?></article>
<?php endforeach; ?>
</section>
<div class="dashboard-grid">
<div class="dashboard-main">
<section class="review-banner"><div><span class="badge badge-purple">A LITTLE PRACTICE GOES A LONG WAY</span><h2>Your next little<br>breakthrough awaits.</h2><p><?php if ($stats['due']): ?><strong><?= (int) $stats['due'] ?> <?= $stats['due'] === 1 ? 'card is' : 'cards are' ?></strong> ready for a fresh look. Take it one question at a time.<?php else: ?>You're all caught up. Add something new, or revisit what you know.<?php endif; ?></p><div class="today-review-snapshot"><div class="progress-caption"><strong>Today’s review snapshot</strong><span><?= $reviewPercent ?>%</span></div><div class="progress-track" role="progressbar" aria-label="Today’s review snapshot" aria-valuenow="<?= $reviewPercent ?>" aria-valuemin="0" aria-valuemax="100"><span class="progress-fill" style="width: <?= $reviewPercent ?>%"></span></div><p class="field-hint"><?= $reviewedLater ?> reviewed today and scheduled later · <?= (int) $stats['due'] ?> due now</p><p class="field-hint">Your due workload changes as more cards become due.</p></div><a class="btn btn-primary" href="<?= e(url('/study')) ?>"><?= icon('study') ?> <?= $stats['due'] ? 'Start today’s review' : 'Explore study options' ?></a></div><div class="review-orbit" aria-hidden="true"><span class="orbit-dot"></span><div class="orbit-card"><?= icon('sparkles',36) ?><strong>Small steps.<br>Lasting knowledge.</strong></div></div></section>
<nav class="quick-actions" aria-label="Quick actions"><a class="quick-action" href="<?= e(url('/decks/create')) ?>"><?= icon('plus',20) ?><span><strong>Create a deck</strong><small>Make room for a new subject</small></span></a><a class="quick-action" href="<?= e(url($decks ? '/decks/'.(int)$decks[0]['id'].'/cards/create' : '/decks/create')) ?>"><?= icon('cards',20) ?><span><strong>Add a flashcard</strong><small><?= $decks ? 'Capture one more idea' : 'Create a deck first' ?></small></span></a><a class="quick-action" href="<?= e(url('/study')) ?>"><?= icon('study',20) ?><span><strong>Start studying</strong><small>A little focus goes a long way</small></span></a><a class="quick-action" href="<?= e(url('/analytics')) ?>"><?= icon('analytics',20) ?><span><strong>View analytics</strong><small>See your learning take shape</small></span></a></nav>
<section class="panel"><div class="panel-heading"><div><p class="eyebrow">MAKE ROOM FOR WHAT MATTERS</p><h2>Your decks</h2></div><a class="text-link" href="<?= e(url('/decks')) ?>">View all decks <?= icon('arrow',16) ?></a></div>
<?php if (!$decks): ?><div class="empty-state"><span class="empty-icon"><?= icon('decks',32) ?></span><h3>A fresh start for your ideas</h3><p>Give your first subject a home. A deck is a collection of questions you'll learn a little better every day.</p><a href="<?= e(url('/decks/create')) ?>" class="btn btn-primary"><?= icon('plus') ?> Create your first deck</a></div>
<?php else: ?><div class="deck-grid compact-decks"><?php foreach (array_slice($decks,0,4) as $deck): ?><article class="deck-card" style="--deck-color: <?= e($deck['color']) ?>"><span class="deck-color"><?= icon('decks',22) ?></span><span class="badge"><?= e($deck['subject'] ?: 'General') ?></span><h3><a href="<?= e(url('/decks/' . ((int) $deck['id']))) ?>"><?= e($deck['title']) ?></a></h3><p><?= e(excerpt($deck['description'] ?: 'Your next learning adventure starts here.',90)) ?></p><div class="deck-meta"><span><?= (int) $deck['card_count'] ?> cards</span><span><?= (int) $deck['due_count'] ?> due</span></div><div class="progress-track" role="progressbar" aria-label="<?= e($deck['title']) ?> mastery" aria-valuenow="<?= (int) $deck['progress'] ?>" aria-valuemin="0" aria-valuemax="100"><span class="progress-fill" style="width: <?= (int) $deck['progress'] ?>%"></span></div><div class="deck-footer"><span><?= (int) $deck['progress'] ?>% mastered</span><a class="text-link" href="<?= e(url('/decks/' . ((int) $deck['id']))) ?>">Open deck <?= icon('arrow',16) ?></a></div></article><?php endforeach; ?></div><?php endif; ?></section>
</div>
<aside class="dashboard-aside">
<section class="panel"><div class="panel-heading"><div><p class="eyebrow">KEEP SHOWING UP</p><h2>Your learning rhythm</h2></div><?= icon('analytics') ?></div><p class="muted">Reviews across the last seven days</p><div class="chart-bars" aria-label="Daily review counts"><?php $maxDaily = max(1,...array_column($daily,'count')); foreach ($daily as $day): ?><div class="chart-column"><span class="chart-value"><?= (int) $day['count'] ?></span><div class="chart-bar-track"><span class="chart-bar" style="height: <?= max(2,round($day['count']/$maxDaily*100)) ?>%"></span></div><span class="chart-label"><?= e($day['label']) ?></span></div><?php endforeach; ?></div><a class="text-link" href="<?= e(url('/analytics')) ?>">Explore your progress <?= icon('arrow',16) ?></a></section>
<section class="panel"><div class="panel-heading"><h2>Recent activity</h2><span class="badge"><?= (int) $stats['reviews'] ?> total</span></div><?php if (!$activity): ?><p class="empty-copy">Your learning story starts with your first review. Each practice session will appear here.</p><?php else: ?><ol class="activity-list"><?php foreach (array_slice($activity,0,4) as $item): ?><li class="activity-item"><span class="activity-icon"><?= icon('check',17) ?></span><div><strong><?= e($item['deck_title']) ?></strong><p><?= e(ucfirst($item['rating'])) ?><?= !empty($item['is_practice']) ? ' · Practice' : ' · Review' ?></p><time datetime="<?= e($item['reviewed_at']) ?>"><?= e(format_date($item['reviewed_at'],'M j · H:i')) ?> UTC</time></div></li><?php endforeach; ?></ol><?php endif; ?></section>
<section class="tip-card"><span class="eyebrow"><?= icon('sparkles',16) ?> A THOUGHT TO TAKE WITH YOU</span><h3>Give your memory a moment to work.</h3><p>Try answering before you reveal the card. The effort of remembering is part of the practice.</p></section>
